const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const afghanistan = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Afghanistan'))
    .geometry();

  const date2017_start = '2017-02-01';
  const date2017_end = '2017-03-01';
  const date2018_start = '2018-02-01';
  const date2018_end = '2018-03-01';

  // 2. Data Acquisition - MODIS Terra LST (8-day)
  const col2017 = ee.ImageCollection('MODIS/006/MOD11A2')
    .filterBounds(afghanistan)
    .filterDate(date2017_start, date2017_end)
    .select('LST_Day_1km');

  const col2018 = ee.ImageCollection('MODIS/006/MOD11A2')
    .filterBounds(afghanistan)
    .filterDate(date2018_start, date2018_end)
    .select('LST_Day_1km');

  const size2017 = await col2017.size().getInfo();
  const size2018 = await col2018.size().getInfo();

  console.log(`Feb 2017 images: ${size2017}`);
  console.log(`Feb 2018 images: ${size2018}`);

  if (size2017 === 0 || size2018 === 0) {
    console.log('No images found for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Create mean composites and apply scale factor
  // MODIS LST scale factor is 0.02, units are Kelvin
  const img2017 = col2017.mean().multiply(0.02);
  const img2018 = col2018.mean().multiply(0.02);

  // 4. Calculate mean temperature for each period
  const stats2017 = await img2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: afghanistan,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2018 = await img2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: afghanistan,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean2017 = stats2017.LST_Day_1km_mean;
  const count2017 = stats2017.LST_Day_1km_count;
  const mean2018 = stats2018.LST_Day_1km_mean;
  const count2018 = stats2018.LST_Day_1km_count;

  console.log(`2017: Mean LST = ${mean2017 ? mean2017.toFixed(2) : 'null'} K, Pixels = ${count2017 || 0}`);
  console.log(`2018: Mean LST = ${mean2018 ? mean2018.toFixed(2) : 'null'} K, Pixels = ${count2018 || 0}`);

  // 5. Validation & Final Answer
  if (count2017 === 0 || count2018 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean2017 == null || mean2018 == null || isNaN(mean2017) || isNaN(mean2018)) {
    console.log('Calculation returned invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if values are in reasonable range (Kelvin: 200-350K typical)
  if (mean2017 < 200 || mean2017 > 350 || mean2018 < 200 || mean2018 > 350) {
    console.log('Temperature values outside reasonable range.');
    console.log('<answer>C3</answer>');
    return;
  }

  const tempDiff = mean2018 - mean2017;
  console.log(`Temperature change: ${tempDiff.toFixed(2)} K`);

  if (tempDiff > 0) {
    console.log('Temperature increased in Feb 2018 vs Feb 2017.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Temperature did not increase in Feb 2018 vs Feb 2017.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
